INSERT INTO localities (name, slug, description, image_url, walkability_score, safety_score, school_rating, avg_price_per_sqft, amenities) VALUES
('Sector 35', 'sector-35-sohna', 'A well-planned residential sector with excellent connectivity to Sohna Road and upcoming infrastructure. Known for affordable builder floors and peaceful environment.', 'https://images.pexels.com/photos/1396122/pexels-photo-1396122.jpeg?auto=compress&cs=tinysrgb&w=800', 75, 82, 4.2, 42000, '{"schools": [{"name": "Delhi Public School", "distance": "4 km"}, {"name": "Ryan International", "distance": "5 km"}], "hospitals": [{"name": "Medanta Hospital", "distance": "8 km"}], "shopping": [{"name": "Omaxe City Centre", "distance": "3 km"}], "transport": [{"name": "Sohna Road", "distance": "2 km"}, {"name": "Proposed Metro Station", "distance": "1.5 km"}]}'),
('Sector 36', 'sector-36-sohna', 'Premium residential sector with luxury high-rise apartments and excellent amenities. Close to major corporate hubs and educational institutions.', 'https://images.pexels.com/photos/259588/pexels-photo-259588.jpeg?auto=compress&cs=tinysrgb&w=800', 80, 85, 4.5, 55000, '{"schools": [{"name": "GD Goenka School", "distance": "3 km"}, {"name": "Amity International", "distance": "5 km"}], "hospitals": [{"name": "Fortis Hospital", "distance": "6 km"}, {"name": "Artemis Hospital", "distance": "7 km"}], "shopping": [{"name": "MGF Metropolitan Mall", "distance": "8 km"}], "transport": [{"name": "Sohna Road", "distance": "1 km"}, {"name": "NH-48", "distance": "4 km"}]}'),
('Sector 63A', 'sector-63a-gurugram', 'Strategic location on Golf Course Extension Road with premium residential projects and excellent connectivity to Cyber City and Golf Course Road.', 'https://images.pexels.com/photos/323780/pexels-photo-323780.jpeg?auto=compress&cs=tinysrgb&w=800', 78, 80, 4.3, 65000, '{"schools": [{"name": "Scottish High School", "distance": "2 km"}, {"name": "Lancers International", "distance": "4 km"}], "hospitals": [{"name": "Medanta Hospital", "distance": "5 km"}], "shopping": [{"name": "South Point Mall", "distance": "3 km"}], "transport": [{"name": "Golf Course Extension Road", "distance": "0.5 km"}, {"name": "Rapid Metro", "distance": "6 km"}]}'),
('Sector 67', 'sector-67-gurugram', 'Emerging residential destination with affordable luxury options. Features wide roads, parks, and proximity to Southern Peripheral Road.', 'https://images.pexels.com/photos/1115803/pexels-photo-1115803.jpeg?auto=compress&cs=tinysrgb&w=800', 72, 78, 4.0, 52000, '{"schools": [{"name": "DPS Sector 45", "distance": "4 km"}, {"name": "Shiv Nadar School", "distance": "5 km"}], "hospitals": [{"name": "Columbia Asia", "distance": "6 km"}], "shopping": [{"name": "DLF South Point", "distance": "4 km"}], "transport": [{"name": "Southern Peripheral Road", "distance": "1 km"}, {"name": "NH-48", "distance": "3 km"}]}'),
('Sector 70', 'sector-70-gurugram', 'Premium locality on Southern Peripheral Road with excellent connectivity. Features luxury builder floors and proximity to Sohna Road.', 'https://images.pexels.com/photos/106399/pexels-photo-106399.jpeg?auto=compress&cs=tinysrgb&w=800', 76, 81, 4.4, 58000, '{"schools": [{"name": "Heritage Xperiential School", "distance": "3 km"}, {"name": "Suncity School", "distance": "4 km"}], "hospitals": [{"name": "Fortis Hospital", "distance": "5 km"}], "shopping": [{"name": "Raheja Mall", "distance": "2 km"}], "transport": [{"name": "Sohna Road", "distance": "1 km"}, {"name": "Southern Peripheral Road", "distance": "0.5 km"}]}'),
('Gwal Pahari', 'gwal-pahari', 'Scenic location nestled in the Aravali foothills offering farmhouses and luxury villas. Known for pristine environment and excellent road connectivity.', 'https://images.pexels.com/photos/1520259/pexels-photo-1520259.jpeg?auto=compress&cs=tinysrgb&w=800', 65, 75, 3.8, 85000, '{"schools": [{"name": "Pathways World School", "distance": "5 km"}, {"name": "GD Goenka World School", "distance": "6 km"}], "hospitals": [{"name": "Medanta Hospital", "distance": "12 km"}], "shopping": [{"name": "Artemis Hospital Complex", "distance": "10 km"}], "transport": [{"name": "Gurgaon-Faridabad Road", "distance": "2 km"}, {"name": "Sohna Road", "distance": "5 km"}]}')
ON CONFLICT (slug) DO NOTHING;

