('M3M Urbana Business Park', 'Sector 67, Gurugram', 'Premium commercial complex with modern office spaces and retail shops. Located on Southern Peripheral Road with excellent visibility from main road. Features high-speed elevators, ample parking, and 24/7 security.', '₹85,00,000', 'commercial', 'available', '1200 sq.ft.', NULL, NULL, 'https://images.pexels.com/photos/323705/pexels-photo-323705.jpeg?auto=compress&cs=tinysrgb&w=1200', ARRAY['https://images.pexels.com/photos/1486322/pexels-photo-1486322.jpeg', 'https://images.pexels.com/photos/323780/pexels-photo-323780.jpeg'], ARRAY['Ground + 11 Floors', '3 Side Open Plot', 'Grand Lobby', 'High-Speed Elevators', '100% Power Backup', 'Ample Parking', '24/7 Security', 'Fire Safety Systems', 'CCTV Surveillance', 'AC Common Areas'], 8500000, 1200, 28.4085, 77.0625, 'Tower A, M3M Urbana Business Park, Sector 67, Gurugram', 'HRERA-GGM-572-2021', 'M3M India', '2024-12-31', true, 7083, true, 'East', 'New', 'Raw', 65),

('Vatika Business Centre', 'Sector 83, Gurugram', 'Strategic commercial development on NH-48 with excellent connectivity to Manesar and Delhi. Ideal for offices, showrooms, and retail. Modern amenities with premium finishing.', '₹65,00,000', 'commercial', 'available', '900 sq.ft.', NULL, NULL, 'https://images.pexels.com/photos/260689/pexels-photo-260689.jpeg?auto=compress&cs=tinysrgb&w=1200', ARRAY['https://images.pexels.com/photos/323705/pexels-photo-323705.jpeg', 'https://images.pexels.com/photos/259588/pexels-photo-259588.jpeg'], ARRAY['Main Road Facing', 'Corner Unit', 'Large Shop Front', 'High Visibility', 'Power Backup', 'Parking', 'Security', 'Fire Safety'], 6500000, 900, 28.4567, 76.9234, 'Vatika Business Centre, Sector 83, Gurugram', 'HRERA-GGM-345-2020', 'Vatika Group', '2024-06-30', true, 7222, true, 'North', 'New', 'Raw', 48),

